    uint64_t *pa0=scratch,*pa1=pa0+kp1,*pa2=pa1+kp1,*ea=pa2+kp1,*tt=ea+kp1;
    uint64_t *v0=tt+kp1,*v1=v0+w,*vm1=v1+w,*v2=vm1+w,*vinf=v2+w;
    uint64_t *ta=vinf+w,*tb=ta+w,*cc1=tb+w,*cc2=cc1+w,*cc3=cc2+w,*te=cc3+w,*tf=te+w,*ksc=tf+w;
