static inline __attribute__((always_inline))
WValue w_ic_bigint_abs(WValue r, WValue *a, int c) {
    (void)a; (void)c;
    /* Tag-sign abs (v4): effective-positive values keep the identity
     * return; effective-negative ones hand out the same buffer with the
     * overlay bit set so header-sign XOR overlay composes positive —
     * O(1), zero allocation, like w_neg. */
    if (__builtin_expect(!w_bigint_effective_negative(r), 1)) return r;
    w_bigint_mark_shared(w_as_bigint(r));
    return r ^ W_BIGINT_SIGN_BIT;
}

static inline __attribute__((always_inline))
WValue bigint_lcm_one_limb(uint64_t x, uint64_t y) {
    uint64_t g = bn_gcd_u64_nonzero(x, y);
    /* Random operands are usually coprime; skip the udiv then. */
    uint64_t q = g == 1 ? x : x / g;
    __uint128_t product = (__uint128_t)q * y;
    uint64_t low = (uint64_t)product;
    uint64_t high = (uint64_t)(product >> 64);
    if (high == 0) return bigint_finish_one_limb(low, 0);
    WBigint *out = bigint_alloc_raw_hot(2);
    out->limbs[0] = low;
    out->limbs[1] = high;
    out->size = 2;
    return bigint_box(out);
}

static __attribute__((noinline))
WValue w_ic_integer_lcm_generic(WValue r, WValue *a, int c) {
    if (c < 1) die("lcm requires 1 argument");
    WValue arg = a[0];
    if (!w_is_integer_any(arg)) die("lcm requires an integer argument");

#if BN_ALGEBRAIC_IDENTITY_FAST
    if (r == arg && w_is_bigint(r))
        return bigint_abs_alias(r);
    if ((arg == w_box_int(1) || arg == w_box_int(-1)) && w_is_bigint(r))
        return bigint_abs_alias(r);
    if ((r == w_box_int(1) || r == w_box_int(-1)) && w_is_bigint(arg))
        return bigint_abs_alias(arg);
#endif

    uint64_t r_scratch, a_scratch;
    int32_t rlen, alen;
    const uint64_t *rl = integer_limbs(r, &r_scratch, &rlen);
    const uint64_t *al = integer_limbs(arg, &a_scratch, &alen);
    int32_t r_abs = rlen < 0 ? -rlen : rlen;
    int32_t a_abs = alen < 0 ? -alen : alen;
    if (r_abs == 0 || a_abs == 0) return w_int(0);

    if (r_abs == 1 && a_abs == 1) {
        /* One-limb pair (inline ints and 1-limb bigints alike): u64 gcd,
         * exact u64 quotient, one 128-bit product, boxed once.  lcm is
         * nonnegative by definition, so magnitudes suffice. */
        return bigint_lcm_one_limb(rl[0], al[0]);
    }

    /* Multi-limb: |r/g * arg| through the direct bigint entries — the
     * w_div/w_mul dispatch preambles are integer-dead weight here.  Random
     * operands are almost always coprime, so a unit gcd skips the exact
     * division (and its allocation) entirely. */
    WValue divisor = bigint_gcd_any(r, arg);
    WValue product;
    if (w_is_int(divisor) && w_as_int(divisor) == 1) {
        product = bigint_mul_any(r, arg);
    } else {
        /* g | r by construction: Jebelean exact division (about half the
         * cost of bigint_div_any's estimate-and-correct path). */
        uint64_t d_scratch;
        int32_t dlen;
        const uint64_t *dl = integer_limbs(divisor, &d_scratch, &dlen);
        int32_t d_abs = dlen < 0 ? -dlen : dlen;
        WValue quotient = bigint_finish_mag_sub(
            mag_divexact(rl, r_abs, dl, d_abs));
        product = bigint_mul_any(quotient, arg);
        if (divisor != r && divisor != arg && divisor != quotient &&
            divisor != product && w_is_bigint(divisor))
            bigint_release_if_live(w_as_bigint(divisor));
        if (quotient != r && quotient != arg && quotient != product &&
            w_is_bigint(quotient))
            bigint_release_if_live(w_as_bigint(quotient));
    }

    if (w_is_int(product)) {
        int64_t pv = w_as_int(product);
        return pv < 0 ? w_box_int(-pv) : product;
    }
    /* lcm is nonnegative. The product is usually a fresh allocation, but the
     * multiply's identity arms can return `arg` itself (quotient == 1), so
     * take the O(1) overlay abs instead of flipping the header in place. */
    if (w_bigint_effective_negative(product)) {
        w_bigint_mark_shared(w_as_bigint(product));
        return product ^ W_BIGINT_SIGN_BIT;
    }
    return product;
}

/* BigInt method callsites know both operands' representation.  Keep the
 * one-limb LCM in their caller and leave
 * mixed/multi-limb coercion in the out-of-line generic implementation. */
static inline __attribute__((always_inline))
WValue w_ic_integer_lcm(WValue r, WValue *a, int c) {
    if (__builtin_expect(c >= 1, 1) && w_is_bigint(r)) {
        WValue arg = a[0];
        if (w_is_bigint(arg)) {
            int32_t rs, as;
            WBigint *rb = w_bigint_view(r, &rs);
            WBigint *ab = w_bigint_view(arg, &as);
            if (__builtin_expect(
                    (rs == 1 || rs == -1) &&
                    (as == 1 || as == -1), 0)) {
                if (r == arg)
                    return bigint_abs_alias(r);   /* lcm(x,x) = |x| */
                return bigint_lcm_one_limb(rb->limbs[0], ab->limbs[0]);
            }
        }
    }
    return w_ic_integer_lcm_generic(r, a, c);
}
